(async () => {
  const d = async (b) => {
    const a = atob(b),
      c = new Uint8Array(a.length);
    for (let i = 0; i < a.length; i++) c[i] = a.charCodeAt(i);
    const blob = new Blob([c]);
    const ds = new DecompressionStream("gzip");
    return await new Response(blob.stream().pipeThrough(ds)).text();
  };
  await Promise.all(
    AVATARS.map(async (e) => {
      e.svg = await d(e.svg);
    }),
  );
  if (typeof onAvatarsReady === "function") onAvatarsReady();
})();
